/**
 * Types describing the `usage.json` file that is generated by `scripts/generate-data.ts`
 * at build time from the raw `data.json`, and the data that the page creates from it.
 *
 * All dates use four-digit years: months are "YYYY-MM" and days are "YYYY-MM-DD".
 */

//
// The usage.json file
//

/**
 * A compact list of counts in which most values are zero. It consists of alternating
 * pairs of an index and the count at that index: `[i0, c0, i1, c1, ...]`. Indices that
 * are not listed have a count of zero
 */
export type SparseCounts = number[];

export interface UsageFile {
  /**
   * All months for which there is data in the form "YYYY-MM", sorted chronologically.
   * The `months` counts of countries and places are indices into this list
   */
  months: string[];

  /**
   * The list of all versions, starting with the empty string that represents builds
   * without a version number, followed by all versions from newest to oldest. The
   * `versions` counts of days are indices into this list
   */
  versions: string[];

  countries: {
    /**
     * The ISO 3166-1 alpha-2 code of the country
     */
    code: string;
    name: string;
    months: SparseCounts;
  }[];

  places: {
    lat: number;
    lng: number;
    months: SparseCounts;
  }[];

  /**
   * The usage per day, sorted chronologically. Days without any starts are not listed
   */
  days: {
    date: string;
    versions: SparseCounts;
  }[];

  /**
   * Maps the day of each release to the version that was released on that day
   */
  releases: Record<string, string>;

  /**
   * For each version, the number of times each profile has been started
   */
  profiles: Record<string, Record<string, number>>;
}

//
// The data used by the page
//

/**
 * The number of starts per month. The keys are in the form "YYYY-MM"
 */
export type MonthlyCounts = Record<string, number>;

/**
 * The usage of a single country
 */
export interface CountryUsage {
  /**
   * The ISO 3166-1 alpha-2 code of the country
   */
  code: string;

  /**
   * The human-readable name of the country
   */
  name: string;

  /**
   * The total number of starts in this country
   */
  total: number;

  byMonth: MonthlyCounts;
}

/**
 * The usage at a single place, which is the approximate location of a city
 */
export interface PlaceUsage {
  lat: number;
  lng: number;

  /**
   * The total number of starts at this place
   */
  total: number;

  byMonth: MonthlyCounts;
}

/**
 * The usage on a single day
 */
export interface DayUsage {
  /**
   * The day in the form "YYYY-MM-DD"
   */
  date: string;

  /**
   * The number of starts for each version. The order is the same as `UsageData.versions`
   */
  counts: number[];

  /**
   * The version that was released on this day, or `null` if there was no release
   */
  release: string | null;
}

export interface UsageData {
  /**
   * All months for which there is data in the form "YYYY-MM", sorted chronologically
   */
  months: string[];

  /**
   * The list of all versions, starting with the empty string that represents builds
   * without a version number, followed by all versions from newest to oldest
   */
  versions: string[];

  countries: CountryUsage[];
  places: PlaceUsage[];

  /**
   * The usage per day, sorted chronologically
   */
  days: DayUsage[];

  /**
   * For each version, the number of times each profile has been started
   */
  profiles: Record<string, Record<string, number>>;
}
